def connessioni_sature(m):
    connessioni = m.get("connections")
    massimo = m.get("max_connections")
    errori = m.get("connection_errors_max_s")
    if connessioni is not None:
        if massimo is not None:
            if connessioni >= massimo - 1:
                return diagnosis("connessioni_sature", "critico", "connessioni", {"connections": connessioni, "max_connections": massimo, "connection_errors_max_s": errori}, "Le connessioni hanno raggiunto il limite di max_connections: individuare i client che tengono molte connessioni aperte, usare un pool di connessioni o chiudere quelle inattive, e valutare un aumento di max_connections.")
    if errori is not None:
        if errori > 0:
            return diagnosis("connessioni_sature", "critico", "connessioni", {"connections": connessioni, "max_connections": massimo, "connection_errors_max_s": errori}, "MySQL sta rifiutando connessioni per max_connections: individuare i client che tengono molte connessioni aperte, usare un pool di connessioni o chiudere quelle inattive, e valutare un aumento di max_connections.")
    return None

def cpu_saturata_carico_query(m):
    cpu = m.get("cpu_pct")
    thr = m.get("threads_running")
    cores = m.get("cpu_cores")
    if cpu is None or thr is None or cores is None:
        return None
    if cores <= 0:
        return None
    if cpu >= 95 and thr >= cores * 2:
        return diagnosis("cpu_saturata_carico_query", "critico", "cpu", {"cpu_pct": cpu, "threads_running": thr, "cpu_cores": cores, "threads_per_core": round(thr / cores, 2)}, "Individuare le query che generano il carico, ottimizzarle o limitarle, e ridistribuire il traffico verso gli altri worker o aumentare le CPU.")
    return None

def query_senza_indice(m):
    cpu = m.get("cpu_pct")
    scan = m.get("select_scan_s")
    if cpu is None or scan is None:
        return None
    join = m.get("select_full_join_s")
    if join is None:
        join = 0
    full = scan + join
    if cpu > 85 and full > 5:
        return diagnosis("query_senza_indice", "critico", "cpu", {"cpu_pct": cpu, "scansioni_complete_s": round(full, 2)}, "CPU satura con molte scansioni complete: trovare le query senza indice (EXPLAIN, log delle slow query) e aggiungere gli indici mancanti.")
    if cpu > 70 and full > 5:
        return diagnosis("query_senza_indice", "attenzione", "cpu", {"cpu_pct": cpu, "scansioni_complete_s": round(full, 2)}, "CPU alta con molte scansioni complete: verificare con EXPLAIN le query pesanti e aggiungere gli indici mancanti.")
    return None

def contesa_lock_righe(m):
    lock = m.get("lock_ms_s")
    if lock is None:
        return None
    attese = round(lock / 1000, 1)
    if lock > 10000:
        return diagnosis("contesa_lock_righe", "critico", "lock", {"lock_ms_s": lock, "sessioni_in_attesa_stimate": attese}, "Molte sessioni sono bloccate su lock di riga InnoDB. Cerca e chiudi la transazione lunga o non terminata (information_schema.innodb_trx, sys.innodb_lock_waits), poi verifica che l'applicazione faccia COMMIT o ROLLBACK.")
    if lock > 5000:
        return diagnosis("contesa_lock_righe", "attenzione", "lock", {"lock_ms_s": lock, "sessioni_in_attesa_stimate": attese}, "Il tempo di attesa sui lock di riga è sopra la norma. Controlla le transazioni aperte da molto tempo e gli UPDATE che toccano le stesse righe.")
    return None
